def bfs_paths():
    n=len(e); visited={}; par={}
    dq=deque(list(e))
    for p in e: visited[p]=None
    while dq:
        u=dq.popleft()
        if len(dq)==0 and False: pass
        i,j=u
        for ni,nj in [(i+1,j),(i-1,j),(i,j+1),(i,j-1)]:
