# Billiard with reflect (flip dir on wall) but only continue while in-bounds each step; terminate when ray exits completely.
from collections import Counter
I=G['Demo pair 6 input']; O=G['Demo pair 6 output']
def f(I,maxstep=400):
    H=len(I);W=len(I[0]);O=[row[:] for row in I]
    es=[(r,c) for r in range(H) for c in range(W) if I[r][c]!=3]
    def mark(r,c):
        if 0<=r<H and 0<=c<W: O[r][c]=5
    for e in es:
        sr,sc=e
        for drn,dcn in [(1,1),(1,-1),(-1,1),(-1,-1)]:
            rr,cc=sr,sc; kd=1
            while kd<maxstep:
                nr,nc=rr+drn,cc+dcn
                vr = 0<=nr<H; vc = 0<=nc<W
                if not(vr and vc):
                    # bounce off whichever edge(s) we'd hit: flip component whose next pos is out
                    if not vr and nc==cc+dcn and 0<=rr+drn<H:
                        drn=-drn; nr=rr+drn
                    elif not vc and rr==rr+drn and 0<=nc+dcn<W:
                        dcn=-dcn; nc=cc+dcn
                    else:
                        break
                    # move again with new dir
                    nr,nc=rr+drn,cc+dcn
                rr,cc=nr,nc
                if kd%2==1: mark(rr,cc)
                else: mark(rr,cc-1);mark(rr,cc);mark(rr,cc+1)
                kd+=1
    return O
